import frappe
from frappe.model.document import Document

class PayProvisionSettlementPreparation(Document):
    def before_save(self):
        # --- from script: Add Preparation Decompte (exec fallback) ---
        script = "if doc.employee:\n \n  date_actuelle_end = frappe.utils.getdate(doc.pay_end_date)\n  date_entree_end = frappe.utils.getdate(doc.pay_hiring_date)\n  \n  start_date = doc.pay_start_date\n  end_date = doc.pay_end_date\n  \n  Net_Paye = 0\n  NombreJourAnn = 0\n  Somme = 0\n  years = 0\n \n  # Calculate the difference in years\n  years = date_actuelle_end.year - date_entree_end.year\n \n  jour_entree = date_entree_end.day\n  mois_entree = date_entree_end.month\n  jour_actuelle = date_actuelle_end.day\n  mois_actuelle = date_actuelle_end.month\n \n  date_entree_end = frappe.utils.getdate(doc.pay_hiring_date)\n  \n  # Difference in years\n  years = date_actuelle_end.year - date_entree_end.year\n  if date_actuelle_end.month < date_entree_end.month or (date_actuelle_end.month == date_entree_end.month and date_actuelle_end.day < date_entree_end.day):\n  years = years\n \n  # Difference in months\n  months = date_actuelle_end.month - date_entree_end.month\n  if date_actuelle_end.day < date_entree_end.day:\n  months = months - 1\n  if months < 0:\n  months = months + 12\n  years = years - 1\n \n  # Compare only the days of the month\n  if date_actuelle_end.day >= date_entree_end.day:\n  days = date_actuelle_end.day - date_entree_end.day\n  else:\n  previous_month = (date_actuelle_end.month - 1) if date_actuelle_end.month > 1 else 12\n  previous_year = date_actuelle_end.year if date_actuelle_end.month > 1 else date_actuelle_end.year - 1\n  days_in_previous_month = (frappe.utils.getdate(f\"{previous_year}-{previous_month + 1}-01\") - frappe.utils.getdate(f\"{previous_year}-{previous_month}-01\")).days\n  days = (date_actuelle_end.day + int(days_in_previous_month)) - date_entree_end.day\n \n  # Display the results\n  doc.pay_seniority_details_text = f\"{years} ans, {months} pay_month, {days} jours\"\n \n  doc.pay_seniority = years\n \n  if days == 0:\n  doc.pay_compensatory_leave_2 = months * 1.5\n  else:\n  doc.pay_compensatory_leave_2 = (months + 1) * 1.5\n \n  if days == 0:\n  doc.pay_13th_month_gratuity = ((mois_actuelle - 1) * 26) / 12\n  else:\n  doc.pay_13th_month_gratuity = (mois_actuelle * 26) / 12\n \n  pay_notice_days = 0\n \n  if doc.pay_categories:\n  if doc.pay_categories.startswith(\"MAO\") or doc.pay_categories.startswith(\"MAL\") or doc.pay_categories.startswith(\"T\"):\n  pay_notice_days = 7 * years\n  doc.pay_notice_days = (pay_notice_days + 14) / 2\n  \n  elif doc.pay_categories.startswith(\"MAT\"):\n  pay_notice_days = 9 * years\n  doc.pay_notice_days = (pay_notice_days + 26) / 2\n  elif doc.pay_categories.startswith(\"CA\"):\n  pay_notice_days = 16 * years\n  doc.pay_notice_days = (pay_notice_days + 78) / 2\n  else:\n  doc.pay_seniority = years\n  \n  #doc.pay_leave_on_notice_2 = (doc.pay_notice_days * 26) / (26 * 12) - 0.55\n  doc.pay_leave_on_notice_2 = (doc.pay_notice_days * 26) / (26 * 12)\n  \n  # Calculate the number of days between the two dates\n  NbreJourPeriode = frappe.utils.date_diff(end_date, start_date)\n  \n  doc.pay_daily_rate = doc.pay_salary / 26\n  \n  # Initialize variables to 0 if they are None\n  doc.pay_compensatory_leave_2 = doc.pay_compensatory_leave_2 or 0\n  doc.pay_worked_and_recovered_days = doc.pay_worked_and_recovered_days or 0\n  doc.pay_loaned_nights = doc.pay_loaned_nights or 0\n  doc.pay_untaken_paid_leave = doc.pay_untaken_paid_leave or 0\n  doc.pay_public_holidays = doc.pay_public_holidays or 0\n  doc.pay_leave_on_notice_2 = doc.pay_leave_on_notice_2 or 0\n  doc.pay_sick_days = doc.pay_sick_days or 0\n  doc.pay_notice_days = doc.pay_notice_days or 0\n  doc.pay_13th_month_gratuity = doc.pay_13th_month_gratuity or 0\n  \n  totalNbreJour = (\n  doc.pay_compensatory_leave_2 +\n  doc.pay_worked_and_recovered_days + \n  doc.pay_loaned_nights + \n  doc.pay_untaken_paid_leave + \n  doc.pay_public_holidays + \n  doc.pay_leave_on_notice_2 + \n  doc.pay_sick_days + \n  doc.pay_notice_days + \n  doc.pay_13th_month_gratuity\n  )\n \n  doc.pay_service_salary = doc.pay_worked_and_recovered_days * doc.pay_daily_rate\n  doc.pay_night_salary = round((doc.pay_loaned_nights / 26) * 1.1 * doc.pay_salary)\n  doc.pay_paid_leave = float(doc.pay_untaken_paid_leave) * float(doc.pay_daily_rate)\n \n  doc.pay_holiday_days = doc.pay_public_holidays * doc.pay_daily_rate\n  doc.pay_leave_pc = (doc.pay_leave_on_notice_2 * doc.pay_daily_rate) + (doc.pay_compensatory_leave_2 * doc.pay_daily_rate)\n  doc.pay_sick_leave = ((doc.pay_sick_days * doc.pay_daily_rate) * 3) / 2\n  doc.pay_notice = doc.pay_daily_rate * doc.pay_notice_days\n  doc.pay_gratuity_amount = doc.pay_daily_rate * doc.pay_13th_month_gratuity\n \n  doc.salaire_prime = doc.pay_bonus or 0\n \n  Brut_imposable = (\n  float(doc.pay_service_salary) +\n  float(doc.pay_night_salary) +\n  float(doc.pay_paid_leave) +\n  float(doc.pay_holiday_days) +\n  float(doc.pay_leave_pc) +\n  float(doc.pay_sick_leave) +\n  float(doc.pay_notice) +\n  float(doc.pay_gratuity_amount) +\n  float(doc.salaire_prime)\n  )\n \n  doc.pay_taxable_gross = Brut_imposable\n \n  doc.pay_housing = doc.pay_housing or 0\n  doc.pay_suspension_days = doc.pay_suspension_days or 0\n  doc.pay_transport = doc.pay_transport or 0\n  doc.pay_family_allowance = doc.pay_family_allowance or 0\n \n  Logement = (doc.pay_housing / 26) * (doc.pay_suspension_days + totalNbreJour)\n  Transport = (doc.pay_transport / 26) * doc.pay_worked_and_recovered_days\n  Allocation_Suspension = doc.pay_daily_rate * (doc.pay_suspension_allowance_pct or 0) * doc.pay_suspension_days\n \n  doc.salaire_logement = Logement\n  doc.salaire_transport = Transport\n  doc.pay_contract_suspension_allowance = Allocation_Suspension\n \n  Brut_Payer = Brut_imposable + Logement + Transport + Allocation_Suspension + doc.pay_family_allowance\n  \n  doc.pay_gross_payable = Brut_Payer\n  \n  pay_inss = Brut_imposable * 0.05\n  pay_ipr = (Brut_imposable - pay_inss) * 0.1\n  \n  pay_net_payable = Brut_Payer - pay_inss - pay_ipr\n  \n  doc.pay_inss = pay_inss\n  doc.pay_ipr = pay_ipr\n  \n  doc.pay_net_payable = pay_net_payable\n "
        exec(script, {"self": self, "frappe": frappe, "doc": self})

